<?php require_once __DIR__ . '/../cdn.php'; \SimpleCdn\Cdn::enable([]); $stats = \SimpleCdn\Cdn::getStats(); ?> <!DOCTYPE html> <html lang="zh-CN"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1.0"> <title>Simple CDN 后台 - 命中率统计</title> <style> * { box-sizing: border-box; } body { font-family: system-ui, -apple-system, Segoe UI, Microsoft YaHei, sans-serif; background: #f5f7fa; color: #111; margin: 0; } .topbar { background: #fff; border-bottom: 1px solid #e2e8f0; padding: 12px 24px; display: flex; align-items: center; gap: 16px; } .topbar h1 { font-size: 16px; margin: 0; color: #0f172a; } .topbar a { color: #2563eb; text-decoration: none; font-size: 13px; } .topbar a:hover { text-decoration: underline; } .topbar .spacer { flex: 1; } .container { max-width: 1000px; margin: 24px auto; padding: 0 20px; } .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; } .card { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; } .card h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; color: #64748b; margin: 0 0 12px; } .card .value { font-size: 32px; font-weight: 700; color: #0f172a; } .card .sub { font-size: 13px; color: #64748b; margin-top: 6px; } .card .rate { font-size: 20px; margin-top: 8px; } .card .rate.ok { color: #059669; } .card .rate.warn { color: #d97706; } .section { background: #fff; border: 1px solid #e2e8f0; border-radius: 10px; padding: 20px; margin-bottom: 20px; } .section h3 { font-size: 16px; margin: 0 0 16px; color: #0f172a; } .table { width: 100%; border-collapse: collapse; } .table th { text-align: left; padding: 10px 12px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; background: #fafbfc; } .table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; font-size: 14px; } .table tr:hover { background: #f8fafc; } .btn { display: inline-block; padding: 8px 14px; background: #2563eb; color: #fff; border: none; border-radius: 6px; font-size: 13px; cursor: pointer; text-decoration: none; } .btn:hover { background: #1d4ed8; } .btn-secondary { background: #f1f5f9; color: #334155; } .btn-secondary:hover { background: #e2e8f0; } .muted { color: #64748b; font-size: 13px; } .empty { color: #94a3b8; font-style: italic; } </style> </head> <body> <div class="topbar"> <h1>命中率统计</h1> <div class="spacer"></div> <a href="index.php" class="btn-secondary">← 返回仪表盘</a> </div> <div class="container"> <div class="grid"> <div class="card"> <h2>总请求数</h2> <div class="value"><?php echo number_format($stats['total']); ?></div> <div class="sub">今日累计请求</div> </div> <div class="card"> <h2>命中数</h2> <div class="value"><?php echo number_format($stats['hit']); ?></div> <div class="sub">缓存命中</div> </div> <div class="card"> <h2>回源数</h2> <div class="value"><?php echo number_format($stats['origin']); ?></div> <div class="sub">未命中回源</div> </div> <div class="card"> <h2>绕过数</h2> <div class="value"><?php echo number_format($stats['bypass']); ?></div> <div class="sub">插件/规则绕过</div> </div> <div class="card"> <h2>命中率</h2> <div class="rate <?php echo $stats['rate'] >= 80 ? 'ok' : 'warn'; ?>"><?php echo $stats['rate']; ?>%</div> <div class="sub">命中 / 总请求</div> </div> </div> <div class="section"> <h3>按路径分片统计</h3> <?php if (empty($stats['paths'])): ?> <p class="empty">暂无路径统计数据。</p> <?php else: ?> <table class="table"> <thead> <tr> <th style="width:25%;">路径</th> <th style="width:15%;">总请求</th> <th style="width:15%;">命中</th> <th style="width:15%;">未命中</th> <th style="width:15%;">回源</th> <th style="width:15%;">命中率</th> </tr> </thead> <tbody> <?php foreach ($stats['paths'] as $path => $data): ?> <tr> <td><?php echo htmlspecialchars($path); ?></td> <td><?php echo number_format($data['total'] ?? 0); ?></td> <td><?php echo number_format($data['hit'] ?? 0); ?></td> <td><?php echo number_format($data['miss'] ?? 0); ?></td> <td><?php echo number_format($data['origin'] ?? 0); ?></td> <td> <span class="rate <?php echo (($data['hit'] ?? 0) / max(($data['total'] ?? 1), 1) * 100) >= 80 ? 'ok' : 'warn'; ?>"> <?php echo number_format((($data['hit'] ?? 0) / max(($data['total'] ?? 1), 1)) * 100, 2); ?>% </span> </td> </tr> <?php endforeach; ?> </tbody> </table> <?php endif; ?> </div> </div> </body> </html>;